select OBJECT_NAME,OBJECT_TYPE,STATUS from USER_OBJECTS where OBJECT_NAME in('RRL_TARE_BALANCE_KEY','RRL_TARE_ASSERT_WRITE','RRL_STOCK_TARE_CMD','RRL_TARE_BALANCE_GUARD','RRL_TARE_OFFER_GUARD','RRL_TARE_ACCEPT_GUARD','RRL_TARE_JOURNAL_GUARD','RRL_STOCK_POSTING_API') order by OBJECT_NAME,OBJECT_TYPE;
select MIGRATION_ID,STATUS from RRL_SCHEMA_MIGRATIONS where MIGRATION_ID='2026-10-10-098-tare-quantity-ledger';
select count(*) INVALID_BALANCES from RRL_TARE_BALANCE where QUANTITY<0 or QUANTITY!=trunc(QUANTITY) or BALANCE_VERSION<1;
